package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseEFMigrationTest extends MigrationTestSupport {
 @Test @Tag("creative") void populatedDSessionHistoryReceivesBoundedOriginalLifetimes(){String url=System.getenv("GREENOCEAN_TEST_DB_URL");assertThat(url).isNotBlank();String schema="qa_ef_"+UUID.randomUUID().toString().replace("-","");var ds=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(ds).schemas(schema).defaultSchema(schema).target("36").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));
 try{UUID user=db.queryForObject("INSERT INTO users(email,password_hash,status,email_verified) VALUES ('legacy-ef@example.test','synthetic-preserved-hash','ACTIVE',TRUE) RETURNING id",UUID.class);db.update("INSERT INTO user_sessions(user_id,refresh_token_hash,created_at,last_used_at,expires_at) VALUES (?,'preserved-hash',CURRENT_TIMESTAMP-INTERVAL '18 hours',CURRENT_TIMESTAMP-INTERVAL '5 minutes',CURRENT_TIMESTAMP+INTERVAL '20 days')",user);var latest=Flyway.configure().dataSource(ds).schemas(schema).defaultSchema(schema).load();latest.migrate();latest.validate();assertThat(db.queryForMap("SELECT client_type,refresh_token_hash,token_version FROM user_sessions WHERE user_id=?",user)).containsEntry("client_type","LEGACY").containsEntry("refresh_token_hash","preserved-hash").containsEntry("token_version",0);assertThat(db.queryForObject("SELECT overall_expires_at=created_at+INTERVAL '24 hours' AND idle_expires_at=last_used_at+INTERVAL '30 minutes' AND expires_at=overall_expires_at FROM user_sessions WHERE user_id=?",Boolean.class,user)).isTrue();assertThat(db.queryForObject("SELECT password_hash FROM users WHERE id=?",String.class,user)).isEqualTo("synthetic-preserved-hash");}
 finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
